def title_case(text: str) -> str:
    """Return ``text`` in headline title case.

    ``text`` is split on single spaces into words. Each word is converted on
    its own and the words are joined again with single spaces:

    1. A word with an uppercase letter anywhere after its first character
       (such as "iPhone", "NASA" or "McKinsey") is kept exactly as written.
    2. Otherwise, if the word with any trailing ``.,:;!?`` characters removed
       is, in lowercase, one of ``SMALL_WORDS`` (a, an, and, as, at, but, by,
       for, in, nor, of, on, or, per, the, to, via), the word is written in
       lowercase -- unless it is the first or the last word of ``text``, in
       which case its first character is uppercased.
    3. Every other word has its first character uppercased.
    """
    words = text.split(" ")
    result = []

    # Find colon position to handle subtitle capitalization
    colon_index = None
    for i, word in enumerate(words):
        if ':' in word:
            colon_index = i
            break

    for index, word in enumerate(words):
        stripped = word.rstrip(_TRAILING_PUNCTUATION)
        is_last = index == len(words) - 1

        # Rule 1: Preserve mixed-case words (uppercase after first character)
        if len(stripped) > 1 and any(c.isupper() for c in stripped[1:]):
            result.append(word)
        # Rule 2: Handle small words
        elif stripped.lower() in SMALL_WORDS:
            if index == 0 or is_last:
                result.append(word.capitalize())
            else:
                result.append(word.lower())
        # Rule 3: Capitalize first character of other words
        else:
            # Special handling for subtitle: only capitalize first non-small word after colon
            if colon_index is not None and index > colon_index:
                # Check if this is the first non-small word after the colon
                is_first_non_small_after_colon = True
                for j in range(colon_index + 1, index):
                    check_word = words[j].rstrip(_TRAILING_PUNCTUATION)
                    if check_word.lower() not in SMALL_WORDS and not (len(check_word) > 1 and any(c.isupper() for c in check_word[1:])):
                        is_first_non_small_after_colon = False
                        break

                if is_first_non_small_after_colon:
                    result.append(word.capitalize())
                elif is_last:
                    result.append(word.capitalize())
                else:
                    result.append(word.lower())
            else:
                result.append(word.capitalize())
    return " ".join(result)
